import { supabase } from '@/integrations/supabase/client';
import type { Database } from '@/integrations/supabase/types';
import { fetchAllRows } from '@/lib/fetchAllRows';

export type Contact = Database['public']['Tables']['contacts']['Row'];

type ContactNoteRow = Database['public']['Tables']['contact_notes']['Row'];

/**
 * Tamanho da página da leitura de notas (mesmo teto que o PostgREST aplica no
 * projeto quando a consulta não tem `.range()`).
 */
export const CONTACT_NOTES_PAGE_SIZE = 1000;

function windowChangePercent(current: number | null, previous: number | null): number | null {
  const curr = current ?? 0;
  const prev = previous ?? 0;
  if (prev === 0) return null;
  return Math.round(((curr - prev) / prev) * 100);
}

export interface SearchContactsParams {
  search_term?: string;
  contact_type_filter?: string | null;
  company_filter?: string | null;
  job_title_filter?: string | null;
  tag_filter?: string | null;
  date_from?: string | null;
  sort_field?: string;
  sort_direction?: string;
  page_size?: number;
  page_offset?: number;
  include_legacy?: boolean;
}

export class ContactService {
  static async searchContacts(params: SearchContactsParams) {
    return supabase.rpc('search_contacts', {
      search_term: params.search_term || '',
      contact_type_filter: params.contact_type_filter || undefined,
      company_filter: params.company_filter || undefined,
      job_title_filter: params.job_title_filter || undefined,
      tag_filter: params.tag_filter || undefined,
      date_from: params.date_from || undefined,
      sort_field: params.sort_field || 'name',
      sort_direction: params.sort_direction || 'asc',
      page_size: params.page_size || 50,
      page_offset: params.page_offset || 0,
      // Só enviado quando verdadeiro: sem ele a RPC usa o default (legados fora).
      ...(params.include_legacy ? { include_legacy: true } : {}),
    });
  }

  static async getCountsByType(includeLegacy = false) {
    return supabase.rpc('contacts_count_by_type', includeLegacy ? { include_legacy: true } : {});
  }

  static async getById(id: string) {
    return supabase.from('contacts').select('*').eq('id', id).maybeSingle();
  }

  /**
   * Retorna a data da última mensagem para cada contact_id da lista.
   * Usa a RPC get_last_message_dates (GROUP BY contact_id, MAX created_at)
   * para evitar truncação pelo limit padrão do PostgREST numa query plana.
   *
   * A RPC retorna exatamente 1 row por contact_id — sem risco de dados
   * incompletos independente do volume de mensagens (hoje: 17.642).
   */
  static async getLastMessageDates(
    contactIds: string[],
  ): Promise<{ data: { contact_id: string; last_message_at: string }[] | null; error: unknown }> {
    if (!contactIds.length) return { data: [], error: null };

    const { data, error } = await supabase.rpc('get_last_message_dates', {
      contact_ids: contactIds,
    });

    return {
      data: (data ?? null) as { contact_id: string; last_message_at: string }[] | null,
      error,
    };
  }

  /**
   * Para os ids de uma página da lista, quem o usuário PODE excluir (mesmo
   * predicado do banco: `can_edit_contact`, ver 20260929770000).
   *
   * Existe para a UI não oferecer "Excluir" em contato fora do alcance do
   * usuário -- antes o item aparecia sempre e o erro só surgia no clique
   * (débito levantado no PR #1187).
   */
  static async getDeletableContacts(
    contactIds: string[],
  ): Promise<{ data: { contact_id: string; can_delete: boolean }[] | null; error: unknown }> {
    if (!contactIds.length) return { data: [], error: null };

    const { data, error } = await supabase.rpc('can_delete_contacts', {
      p_ids: contactIds,
    });

    return {
      data: (data ?? null) as { contact_id: string; can_delete: boolean }[] | null,
      error,
    };
  }

  static async fetchNotes(contactId: string) {
    // Leitura PAGINADA: um `select()` sem `.range()` devolve só a primeira página
    // (teto do projeto, 1000 linhas) e as notas do fim da lista sumiam em silêncio.
    // A ordem `created_at desc` + `id desc` (chave única) é o que garante que a
    // página seguinte continue de onde a anterior parou — sem duplicar nota nem
    // pular a última linha de uma página empatada no mesmo instante.
    const { rows: data, error } = await fetchAllRows<ContactNoteRow>(
      (from, to) =>
        supabase
          .from('contact_notes')
          .select(`id, contact_id, author_id, content, category, is_done, due_date, created_at, updated_at`)
          .eq('contact_id', contactId)
          .order('created_at', { ascending: false })
          .order('id', { ascending: false })
          .range(from, to),
      { pageSize: CONTACT_NOTES_PAGE_SIZE },
    );

    // Erro no meio da leitura: sobe em vez de devolver uma lista parcial como se
    // fosse o conjunto inteiro de notas do contato.
    if (error) throw new Error(error.message);

    const authorIds = [...new Set((data || []).map(n => n.author_id).filter(Boolean))];
    let authors: { id: string, name: string | null, avatar_url: string | null }[] = [];

    if (authorIds.length > 0) {
      const { data: authorsData } = await supabase
        .from('profiles')
        .select('id, name, avatar_url')
        .in('id', authorIds);
      authors = authorsData || [];
    }

    const authorsMap = new Map(authors.map(a => [a.id, a]));
    return (data || []).map(note => ({
      ...note,
      author: authorsMap.get(note.author_id),
    }));
  }

  static async addNote(
    contactId: string,
    authorId: string,
    content: string,
    options?: { category?: string; dueDate?: string | null },
  ) {
    const { data, error } = await supabase
      .from('contact_notes')
      .insert({
        contact_id: contactId,
        author_id: authorId,
        content,
        category: options?.category ?? 'note',
        due_date: options?.dueDate ?? null,
      })
      .select()
      .single();

    // O PostgREST responde `{ data, error }` e NÃO rejeita a promise: sem este
    // `throw` a mutation de quem chama cairia em `onSuccess` com a nota não salva.
    if (error) throw error;
    return data;
  }

   static async deleteNote(noteId: string) {
     const { error } = await supabase.from('contact_notes').delete().eq('id', noteId);
     if (error) throw error;
   }

   static async updateNote(
     noteId: string,
     updates: Partial<{ content: string; is_done: boolean; due_date: string | null }>,
   ) {
     const { data, error } = await supabase.from('contact_notes').update(updates).eq('id', noteId).select().single();
     if (error) throw error;
     return data;
   }
 
   static async fetchCustomFields(contactId: string) {
     return supabase
       .from('contact_custom_fields')
       .select('*')
       .eq('contact_id', contactId)
       .order('field_name');
   }
 
   static async upsertCustomField(payload: Database['public']['Tables']['contact_custom_fields']['Insert']) {
     return supabase.from('contact_custom_fields').upsert(payload);
   }
 
   static async deleteCustomField(fieldId: string) {
     return supabase.from('contact_custom_fields').delete().eq('id', fieldId);
   }
 
   static async fetchEnrichedData(contactId: string) {
     return supabase
       .from('contacts')
       // A4-D (onda 2): as 6 colunas de endereço entram aqui. Sem elas o painel abria o editor com
      // `address`/`city`/`postal_code` vazios e o Salvar gravava esse vazio por cima do endereço.
      // Item 5 (onda 2): latitude/longitude entram pelo mesmo motivo — o editor precisa abrir com a
      // coordenada para poder preservá-la (o Salvar é por diferença; não tocar = não gravar).
      .select('company, job_title, nickname, surname, contact_type, ai_sentiment, ai_priority, channel_type, address, address_number, city, neighborhood, postal_code, state, latitude, longitude')
       .eq('id', contactId)
       .single();
   }
 
   static async fetchAITags(contactId: string) {
     return supabase
       .from('ai_conversation_tags')
       .select('id, tag_name, confidence, source')
       .eq('contact_id', contactId)
       .order('confidence', { ascending: false });
   }
 
   static async fetchSLA(contactId: string) {
     return supabase
       .from('conversation_sla')
       .select('first_response_breached, resolution_breached, first_response_at, resolved_at')
       .eq('contact_id', contactId)
       .order('created_at', { ascending: false })
       .limit(1)
       .maybeSingle();
   }

  static async fetchStats(contactId: string) {
    const DAY_MS = 24 * 60 * 60 * 1000;
    const windowStart = new Date(Date.now() - 30 * DAY_MS).toISOString();
    const prevWindowStart = new Date(Date.now() - 60 * DAY_MS).toISOString();

    const headCount = async (
      table: 'messages' | 'conversation_sla',
      dateColumn: 'created_at' | 'first_message_at',
      gte?: string,
      lt?: string,
    ) => {
      let q = supabase.from(table).select('id', { count: 'exact', head: true }).eq('contact_id', contactId);
      if (gte) q = q.gte(dateColumn, gte);
      if (lt) q = q.lt(dateColumn, lt);
      const { count, error } = await q;
      if (error) throw error;
      return count ?? 0;
    };

    const [
      messageCount,
      recentMessageCount,
      prevMessageCount,
      conversationCount,
      recentConversationCount,
      prevConversationCount,
    ] = await Promise.all([
      headCount('messages', 'created_at'),
      headCount('messages', 'created_at', windowStart),
      headCount('messages', 'created_at', prevWindowStart, windowStart),
      headCount('conversation_sla', 'first_message_at'),
      headCount('conversation_sla', 'first_message_at', windowStart),
      headCount('conversation_sla', 'first_message_at', prevWindowStart, windowStart),
    ]);

    const { data: csatData } = await supabase.from('csat_surveys').select('rating').eq('contact_id', contactId);
    const csatAvg = csatData && csatData.length > 0 ? csatData.reduce((sum, s) => sum + s.rating, 0) / csatData.length : null;

    const { data: agentMessages } = await supabase
      .from('messages')
      .select('created_at, sender')
      .eq('contact_id', contactId)
      .order('created_at', { ascending: true })
      .limit(200);

    let totalResponseTime = 0;
    let responseCount = 0;
    if (agentMessages) {
      for (let i = 1; i < agentMessages.length; i++) {
        if (agentMessages[i].sender === 'agent' && agentMessages[i - 1].sender === 'contact') {
          const diff = new Date(agentMessages[i].created_at).getTime() - new Date(agentMessages[i - 1].created_at).getTime();
          totalResponseTime += diff;
          responseCount++;
        }
      }
    }

    return {
      totalMessages: messageCount || 0,
      avgResponseTimeMinutes: responseCount > 0 ? Math.round(totalResponseTime / (responseCount * 60000)) : 0,
      totalConversations: conversationCount || 0,
      messagesChangePercent: windowChangePercent(recentMessageCount, prevMessageCount),
      conversationsChangePercent: windowChangePercent(recentConversationCount, prevConversationCount),
      csatAverage: csatAvg,
      csatCount: csatData?.length || 0,
    };
  }
}
